114: /// A CallbackRecorder helps tests whether callbacks get called correctly.
115: /// You'll see it used in tests that deal with callbacks.
116: /// The names should be descriptive enough so that the tests make sense,
117: /// so it's not necessary to fully understand the implementation,
118: /// though you are welcome to.
119: struct CallbackRecorder {
120:     // Note that this `Cell` is https://doc.rust-lang.org/std/cell/
121:     // a mechanism to allow internal mutability,
122:     // distinct from the cells (input cells, compute cells) in the reactor
123:     value: std::cell::Cell<Option<i32>>,
124: }
125: 
126: impl CallbackRecorder {
127:     fn new() -> Self {
128:         CallbackRecorder {
129:             value: std::cell::Cell::new(None),
130:         }
131:     }
132: 
133:     fn expect_to_have_been_called_with(&self, v: i32) {
134:         assert_ne!(
135:             self.value.get(),
136:             None,
137:             "Callback was not called, but should have been"
138:         );
139:         assert_eq!(
140:             self.value.replace(None),
141:             Some(v),
142:             "Callback was called with incorrect value"
143:         );
144:     }
145: 
146:     fn expect_not_to_have_been_called(&self) {
147:         assert_eq!(
148:             self.value.get(),
149:             None,
150:             "Callback was called, but should not have been"
151:         );
152:     }
153: 
154:     fn callback_called(&self, v: i32) {
155:         assert_eq!(
156:             self.value.replace(Some(v)),
157:             None,
158:             "Callback was called too many times; can't be called with {v}"
159:         );
160:     }
161: }
