/// `InputCellId` is a unique identifier for an input cell.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct InputCellId(usize);
/// `ComputeCellId` is a unique identifier for a compute cell.
/// Values of type `InputCellId` and `ComputeCellId` should not be mutually assignable,
/// demonstrated by the following tests:
///
/// ```compile_fail
/// let mut r = react::Reactor::new();
/// let input: react::ComputeCellId = r.create_input(111);
/// ```
///
/// ```compile_fail
/// let mut r = react::Reactor::new();
/// let input = r.create_input(111);
/// let compute: react::InputCellId = r.create_compute(&[react::CellId::Input(input)], |_| 222).unwrap();
/// ```
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ComputeCellId(usize);
/// `CallbackId` is a unique identifier for a callback registered on a compute cell.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CallbackId(usize);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CellId {
    Input(InputCellId),
    Compute(ComputeCellId),
}

#[derive(Debug, PartialEq, Eq)]
pub enum RemoveCallbackError {
    NonexistentCell,
    NonexistentCallback,
}

/// A change-notification callback registered on a compute cell.
///
/// The `'a` lifetime lets a callback borrow from data that outlives the `Reactor`
/// (for example a test's `CallbackRecorder`), without requiring the callback to be
/// `'static`.
struct Callback<'a, T> {
    id: CallbackId,
    callback: Box<dyn FnMut(T) + 'a>,
}

/// A compute cell: a value derived from its dependencies via `compute_func`.
struct ComputeCell<'a, T> {
    dependencies: Vec<CellId>,
    compute_func: Box<dyn Fn(&[T]) -> T + 'a>,
    value: T,
    callbacks: Vec<Callback<'a, T>>,
}

pub struct Reactor<'a, T> {
    /// Values of input cells, indexed by `InputCellId`.
    inputs: Vec<T>,
    /// Compute cells, indexed by `ComputeCellId`.
    computes: Vec<ComputeCell<'a, T>>,
    /// Counter used to hand out unique `CallbackId`s.
    next_callback_id: usize,
}

// You are guaranteed that Reactor will only be tested against types that are Copy + PartialEq.
impl<'a, T: Copy + PartialEq> Reactor<'a, T> {
    pub fn new() -> Self {
        Reactor {
            inputs: Vec::new(),
            computes: Vec::new(),
            next_callback_id: 0,
        }
    }

    // Creates an input cell with the specified initial value, returning its ID.
    pub fn create_input(&mut self, initial: T) -> InputCellId {
        let id = InputCellId(self.inputs.len());
        self.inputs.push(initial);
        id
    }

    // Creates a compute cell with the specified dependencies and compute function.
    // The compute function is expected to take in its arguments in the same order as specified in
    // `dependencies`.
    //
    // If any dependency doesn't exist, returns an Err with that nonexistent dependency.
    //
    // Notice that there is no way to *remove* a cell.
    // This means that you may assume, without checking, that if the dependencies exist at creation
    // time they will continue to exist as long as the Reactor exists.
    pub fn create_compute<F: Fn(&[T]) -> T + 'a>(
        &mut self,
        dependencies: &[CellId],
        compute_func: F,
    ) -> Result<ComputeCellId, CellId> {
        // Reject (without mutating anything) if any dependency does not exist.
        for &dep in dependencies {
            match dep {
                CellId::Input(id) if id.0 < self.inputs.len() => {}
                CellId::Compute(id) if id.0 < self.computes.len() => {}
                other => return Err(other),
            }
        }

        // Evaluate the compute function against the current dependency values
        // to establish the cell's initial value.
        let dep_values: Vec<T> = dependencies
            .iter()
            .map(|dep| self.value(*dep).unwrap())
            .collect();
        let value = compute_func(&dep_values);

        let id = ComputeCellId(self.computes.len());
        self.computes.push(ComputeCell {
            dependencies: dependencies.to_vec(),
            compute_func: Box::new(compute_func),
            value,
            callbacks: Vec::new(),
        });
        Ok(id)
    }

    // Retrieves the current value of the cell, or None if the cell does not exist.
    pub fn value(&self, id: CellId) -> Option<T> {
        match id {
            CellId::Input(id) => self.inputs.get(id.0).copied(),
            CellId::Compute(id) => self.computes.get(id.0).map(|cell| cell.value),
        }
    }

    // Sets the value of the specified input cell.
    //
    // Returns false if the cell does not exist.
    pub fn set_value(&mut self, id: InputCellId, new_value: T) -> bool {
        let idx = id.0;
        if idx >= self.inputs.len() {
            return false;
        }
        self.inputs[idx] = new_value;

        // Recompute every compute cell in creation order. Because a cell's
        // dependencies must exist before the cell is created, creation order is
        // a valid topological order: when we recompute a cell, all of its
        // dependencies (which have lower indices) are already up to date.
        //
        // Fire a cell's callbacks only if its value changed, passing the new
        // (final) value.
        for i in 0..self.computes.len() {
            // Gather the dependency values first so that all immutable borrows
            // of `self` are released before we mutate the cell below.
            let dep_values: Vec<T> = self.computes[i]
                .dependencies
                .iter()
                .map(|dep| self.value(*dep).unwrap())
                .collect();
            let recomputed = (self.computes[i].compute_func)(&dep_values);
            if recomputed != self.computes[i].value {
                self.computes[i].value = recomputed;
                for cb in self.computes[i].callbacks.iter_mut() {
                    (cb.callback)(recomputed);
                }
            }
        }

        true
    }

    // Adds a callback to the specified compute cell.
    //
    // Returns the ID of the just-added callback, or None if the cell doesn't exist.
    pub fn add_callback<F: FnMut(T) + 'a>(
        &mut self,
        id: ComputeCellId,
        callback: F,
    ) -> Option<CallbackId> {
        let cell = self.computes.get_mut(id.0)?;
        let cb_id = CallbackId(self.next_callback_id);
        self.next_callback_id += 1;
        cell.callbacks.push(Callback {
            id: cb_id,
            callback: Box::new(callback),
        });
        Some(cb_id)
    }

    // Removes the specified callback, using an ID returned from add_callback.
    //
    // Returns an Err if either the cell or callback does not exist.
    pub fn remove_callback(
        &mut self,
        cell: ComputeCellId,
        callback: CallbackId,
    ) -> Result<(), RemoveCallbackError> {
        let cell = self
            .computes
            .get_mut(cell.0)
            .ok_or(RemoveCallbackError::NonexistentCell)?;
        let pos = cell
            .callbacks
            .iter()
            .position(|cb| cb.id == callback)
            .ok_or(RemoveCallbackError::NonexistentCallback)?;
        cell.callbacks.remove(pos);
        Ok(())
    }
}

